def _job_kinds(include_content: bool) -> None:
    suffix = ", 'content_revision'" if include_content else ""
    for table, name, kinds in (
        (
            "jobs",
            "ck_jobs_job_kind",
            "'diagnostic', 'document_inspection', 'configuration_probe', 'material_parse'",
        ),
        (
            "job_artifacts",
            "ck_job_artifacts_job_artifact_kind",
            "'document_inspection', 'configuration_probe', 'material_parse'",
        ),
    ):
        op.drop_constraint(op.f(name), table, type_="check")
        op.create_check_constraint(op.f(name), table, f"kind IN ({kinds}{suffix})")


def _revision_input_fixed(include_run: bool) -> None:
    run_check = "OR NEW.run_id IS DISTINCT FROM OLD.run_id" if include_run else ""
    op.execute(f"""
        CREATE OR REPLACE FUNCTION thesis_pilot_revision_input_fixed() RETURNS trigger
        LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP = 'DELETE' THEN
                RAISE EXCEPTION 'Revision candidates cannot be deleted' USING ERRCODE = '23514';
            END IF;
            IF NEW.id IS DISTINCT FROM OLD.id
                OR NEW.document_id IS DISTINCT FROM OLD.document_id
                OR NEW.base_version IS DISTINCT FROM OLD.base_version
                OR NEW.input_json::text IS DISTINCT FROM OLD.input_json::text
                OR NEW.policy_version IS DISTINCT FROM OLD.policy_version
                OR NEW.policy_digest IS DISTINCT FROM OLD.policy_digest
                OR NEW.generation_token IS DISTINCT FROM OLD.generation_token
                OR NEW.producer IS DISTINCT FROM OLD.producer
                {run_check}
                OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
                RAISE EXCEPTION 'Revision inputs are immutable' USING ERRCODE = '23514';
            END IF;
            RETURN NEW;
        END;
        $$
    """)
